\draw[blue!75!black] (A) -- (H);
\draw[thin] ($(H)!0.18cm!(A)$) -- ($($(H)!0.18cm!(A)$)+($(H)!0.18cm!(C)$)-(H)$) -- ($(H)!0.18cm!(C)$);
